from datetime import date, timedelta
import calendar


def recur(start: str, rule: str, count: int) -> list[str]:
    wd_map = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
    start_date = date.fromisoformat(start)
    tokens = rule.split(" ")
    freq = tokens[0]
    k = int(tokens[1])
    res: list[str] = []

    if freq == "DAILY":
        for i in range(count):
            res.append((start_date + timedelta(days=i * k)).isoformat())
        return res

    if freq == "WEEKLY":
        target_days = sorted(wd_map[d] for d in tokens[2].split(","))
        week0_mon = start_date - timedelta(days=start_date.weekday())
        w = 0
        while True:
            week_mon = week0_mon + timedelta(days=w * 7)
            for wd in target_days:
                d = week_mon + timedelta(days=wd)
                if d >= start_date:
                    res.append(d.isoformat())
                    if len(res) == count:
                        return res
            w += k

    if freq == "MONTHLY":
        base_months = start_date.year * 12 + (start_date.month - 1)
        m_idx = 0
        if len(tokens) == 3:
            target_day = int(tokens[2])
            while True:
                y, m0 = divmod(base_months + m_idx, 12)
                m = m0 + 1
                days_in_month = calendar.monthrange(y, m)[1]
                day = days_in_month if target_day == -1 else target_day
                if 1 <= day <= days_in_month:
                    d = date(y, m, day)
                    if d >= start_date:
                        res.append(d.isoformat())
                        if len(res) == count:
                            return res
                m_idx += k
        else:
            n = int(tokens[2])
            wd = wd_map[tokens[3]]
            while True:
                y, m0 = divmod(base_months + m_idx, 12)
                m = m0 + 1
                first_wd, days_in_month = calendar.monthrange(y, m)
                first_occ = 1 + (wd - first_wd) % 7
                if n == -1:
                    day = first_occ + ((days_in_month - first_occ) // 7) * 7
                else:
                    day = first_occ + (n - 1) * 7
                if day <= days_in_month:
                    d = date(y, m, day)
                    if d >= start_date:
                        res.append(d.isoformat())
                        if len(res) == count:
                            return res
                m_idx += k

    if freq == "YEARLY":
        mm, dd = map(int, tokens[2].split("-"))
        y = start_date.year
        while True:
            try:
                d = date(y, mm, dd)
            except ValueError:
                y += k
                continue
            if d >= start_date:
                res.append(d.isoformat())
                if len(res) == count:
                    return res
            y += k

    raise ValueError(f"Unsupported rule: {rule}")
